  'Números alinhados à direita': <String>['Right-aligned numbers', 'Números alinhados à direita', 'Números alineados a la derecha', 'Nombres alignés à droite'],
  'Nunca aparece.': <String>['Never appears.', 'Nunca aparece.', 'Nunca aparece.', 'N\'apparaît jamais.'],
